// ActiveValidatorIndices filters out active validators based on validator status
// and returns their indices in a list.
//
// WARNING: This function may be used with state.ReadOnlyValidator objects without copying,
// so the returned indices should be used read-only or with caution to avoid unintended mutations.
func ActiveValidatorIndices(ctx context.Context, s state.ReadOnlyValidators, epoch primitives.Epoch) ([]primitives.ValidatorIndex, error) {
    _, span := trace.StartSpan(ctx, \"helpers.ActiveValidatorIndices\")
    defer span.End()

    if epoch >= params.BeaconConfig().FarFutureEpoch {
        return nil, errFarFutureEpoch
    }

    indices := make([]primitives.ValidatorIndex, 0)
    if err := s.ReadFromEveryValidator(func(idx int, val state.ReadOnlyValidator) error {
        if helpers.IsActiveValidatorUsingTrie(val, epoch) {
            indices = append(indices, primitives.ValidatorIndex(idx))
        }
        return nil
    }); err != nil {
        return nil, errors.Wrap(err, \"could not read validators\")
    }
    return indices, nil
}

// IsActiveValidatorUsingTrie checks if a validator is active at a given epoch.
// Active validators are those whose activation_epoch <= epoch < exit_epoch.
func IsActiveValidatorUsingTrie(validator state.ReadOnlyValidator, epoch primitives.Epoch) bool {
    return validator.ActivationEpoch() <= epoch && epoch < validator.ExitEpoch()
}
